/**
 * Renders downloadable documents (court forms, exam notes, papers,
 * revision charts) into clean printable PDFs. The generated file is kept
 * in memory (object URLs) so Open / Share / Print work offline within the
 * session; "Download" also saves it to the browser's download folder.
 * Bare Acts are never passed through here.
 */

const PAGE = { width: 612, height: 792 };
const MARGIN = 56;

const cache = new Map<string, Blob>();

export const PDFBuilder = {
  fileExists: (fileName: string): boolean => cache.has(fileName),
  deleteFile: (fileName: string): void => {
    cache.delete(fileName);
  },
  blob: (fileName: string): Blob | undefined => cache.get(fileName),

  /** Renders the document and keeps the result. Returns the blob. */
  async makePDF(title: string, subtitle: string, paragraphs: string[], fileName: string): Promise<Blob | null> {
    try {
      // jsPDF is only pulled in when a document is actually generated.
      const { jsPDF } = await import("jspdf");
      const doc = new jsPDF({ unit: "pt", format: [PAGE.width, PAGE.height] });
      const contentWidth = PAGE.width - MARGIN * 2;
      let y = MARGIN;

      const block = (text: string, size: number, style: "normal" | "bold", color: [number, number, number], spacingAfter: number, lineHeight = 1.35) => {
        doc.setFont("helvetica", style);
        doc.setFontSize(size);
        doc.setTextColor(...color);
        const lines = doc.splitTextToSize(text, contentWidth) as string[];
        const height = lines.length * size * lineHeight;
        if (y + height > PAGE.height - MARGIN) {
          doc.addPage();
          y = MARGIN;
        }
        doc.text(lines, MARGIN, y + size, { lineHeightFactor: lineHeight });
        y += height + spacingAfter;
      };

      block("LEXINDIA · LEGAL REFERENCE", 9, "bold", [90, 87, 102], 14);
      block(title, 21, "bold", [0, 0, 0], 6);
      if (subtitle) block(subtitle, 11, "normal", [90, 87, 102], 18);
      for (const paragraph of paragraphs) block(paragraph, 11.5, "normal", [0, 0, 0], 11, 1.45);
      block("Generated by LexIndia · A legal reference, not legal advice.", 8.5, "normal", [128, 128, 128], 0);

      const blob = doc.output("blob");
      cache.set(fileName, blob);
      return blob;
    } catch (error) {
      console.warn("[LexIndia] PDF generation failed", error);
      return null;
    }
  },

  /** Saves the generated PDF through the browser's download flow. */
  saveToDevice(fileName: string): void {
    const blob = cache.get(fileName);
    if (!blob) return;
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = fileName;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 4000);
  },

  /** Opens the PDF in a new tab (the browser's viewer). */
  open(fileName: string): void {
    const blob = cache.get(fileName);
    if (!blob) return;
    const url = URL.createObjectURL(blob);
    window.open(url, "_blank", "noopener");
    window.setTimeout(() => URL.revokeObjectURL(url), 60000);
  },

  /** Prints through a hidden frame so the system print dialog appears. */
  print(fileName: string): void {
    const blob = cache.get(fileName);
    if (!blob) return;
    const url = URL.createObjectURL(blob);
    const frame = document.createElement("iframe");
    frame.style.position = "fixed";
    frame.style.right = "0";
    frame.style.bottom = "0";
    frame.style.width = "0";
    frame.style.height = "0";
    frame.style.border = "0";
    frame.src = url;
    frame.onload = () => {
      try {
        frame.contentWindow?.focus();
        frame.contentWindow?.print();
      } catch {
        window.open(url, "_blank", "noopener");
      }
      window.setTimeout(() => {
        frame.remove();
        URL.revokeObjectURL(url);
      }, 60000);
    };
    document.body.appendChild(frame);
  },

  /** Native share sheet when available (mobile browsers), else download. */
  async share(fileName: string, title: string): Promise<void> {
    const blob = cache.get(fileName);
    if (!blob) return;
    const file = new File([blob], fileName, { type: "application/pdf" });
    const nav = navigator as Navigator & { canShare?: (data: ShareData) => boolean };
    if (nav.share && nav.canShare?.({ files: [file] })) {
      try {
        await nav.share({ files: [file], title });
        return;
      } catch {
        // fall through to download
      }
    }
    this.saveToDevice(fileName);
  },
};
